```python
from collections import OrderedDict


class LRUCache:
    """Least Recently Used cache backed by OrderedDict."""

    def __init__(self, capacity):
        """Initialize cache with given capacity."""
        if capacity <= 0:
            raise ValueError("Capacity must be positive")
        self.capacity = capacity
        self.cache = OrderedDict()
        self.hits = 0
        self.misses = 0

    def get(self, key):
        """Get value by key, marking it as recently used."""
        if key not in self.cache:
            self.misses += 1
            return None
        self.hits += 1
        self.cache.move_to_end(key)
        return self.cache[key]

    def put(self, key, value):
        """Insert or update key-value pair, evicting LRU on overflow."""
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)

    def stats(self):
        """Return cache statistics."""
        return {
            "hits": self.hits,
            "misses": self.misses,
            "size": len(self.cache),
        }

    def __len__(self):
        return len(self.cache)

    def __contains__(self, key):
        return key in self.cache

    def clear(self):
        """Remove all items."""
        self.cache.clear()
        self.hits = 0
        self.misses = 0

    def __repr__(self):
        return f"LRUCache(capacity={self.capacity}, size={len(self.cache)})"
